from pathlib import Path
R=Path(__file__).resolve().parents[1]
isolation='''<script>(()=>{const d=new Map(),s={getItem:k=>d.get(k)??null,setItem:(k,v)=>d.set(k,String(v)),removeItem:k=>d.delete(k),clear:()=>d.clear(),key:i=>[...d.keys()][i]??null,get length(){return d.size}};Object.defineProperty(window,'localStorage',{value:s});Object.defineProperty(window,'sessionStorage',{value:s});})();</script>'''
payload='''<section style="position:fixed;right:4px;top:4px;z-index:999999;background:#162636;color:white;padding:8px;font:12px system-ui;max-width:360px"><button id="pauseQAStart">Start pause tests</button><button id="pauseQATest">Run checks</button><button id="pauseQAGrey">Grey friend</button><button id="pauseQAColor">Resume friend</button><button id="pauseQAStage">Stage friend</button><button id="pauseQALegacy">Load old save</button><pre id="pauseQAResult" style="max-height:200px;overflow:auto">Ready</pre></section><script type="module">
const out=document.getElementById('pauseQAResult');let baseline=null;
document.getElementById('pauseQAStart').onclick=async()=>{try{while(!window.__BF3||!window.HERO3D?.ready)await new Promise(r=>setTimeout(r,50));const b=__BF3;await b.briarReady;b.loadMode('rl');b.meta.classUnlocked.warrior=true;b.meta.classId='warrior';b.meta.hubTutDone=true;b.meta.introSeen=true;b.enterZone(0);document.body.classList.remove('t-title','t-attract');while(BF_LOADING.active)await new Promise(r=>setTimeout(r,50));b.G._tutorialSafe=true;b.update(.016);b.openPause();baseline={time:b.G.time,hp:b.G.p.hp,x:b.G.p.x};out.textContent=JSON.stringify({started:true,pause:b.pauseState(),baseline});}catch(e){out.textContent=e.stack;}};
document.getElementById('pauseQATest').onclick=async()=>{try{const b=__BF3,p=b.G.p,results=[],assert=(v,name)=>{if(!v)throw Error(name);results.push(name);};assert(b.G.time===baseline.time,'real idle wall time frozen');b.G._tutorialSafe=false;p.invuln=0;b.hurtPlayer(5,p.x+5,p.z,'QA');for(let i=0;i<30;i++)b.update(.016);assert(b.G.time===baseline.time&&p.hp===baseline.hp,'solo simulation and damage frozen');document.getElementById('optBtn').click();b.update(.1);assert(b.pauseState().frozen&&b.G.time===baseline.time,'Settings keeps time frozen');__BF_SOCIAL_API.resume();b.update(.016);assert(!b.pauseState().active&&b.G.time>baseline.time,'resume advances time');b.MP.active=true;b.MP.isHost=true;b.MP.pvp=false;b.MP.conns=[];b.MP.myId='pause-fixture';b.openPause();let t=b.G.time,h=p.hp,x=p.x,y=p.y,z=p.z;b.hurtPlayer(99,p.x+5,p.z,'QA');for(let i=0;i<8;i++)b.update(.016);assert(b.G.time>t&&p.hp===h,'co-op world advances without paused damage');assert(p.x===x&&p.y===y&&p.z===z,'co-op paused position held');const packet=b.MP.selfState();assert(packet.busy==='Paused','paused packet');let peer=b.MP.mkPeer({...packet,id:'qa-friend',name:'Paused friend',x:p.x+60,z:p.z+80});b.MP.peers['qa-friend']=peer;assert(b.MP.snap(peer).busy==='Paused','host relay keeps paused status');__BF_SOCIAL_API.resume();assert(b.MP.selfState().busy!=='Paused','resume clears presence');p.invuln=0;h=p.hp;b.hurtPlayer(5,p.x+5,p.z,'QA');assert(p.hp<h,'resume removes damage protection');b.G._tutorialSafe=true;out.textContent=JSON.stringify({passed:results,peer:peer.busy,pause:b.pauseState()},null,2);}catch(e){out.textContent=e.stack;}};
document.getElementById('pauseQALegacy').onclick=async()=>{try{const b=__BF3;b.MP.active=false;b.MP.peers={};b.loadMode('rl');Object.assign(b.meta,JSON.parse(JSON.stringify(LEGACY_SAVE)));b.continueRun();while(BF_LOADING.active)await new Promise(r=>setTimeout(r,50));b.G._tutorialSafe=true;out.textContent=JSON.stringify({oldSaveLoaded:true,level:b.G.p.level,gold:b.meta.gold,classId:b.meta.classId,classState:b.classState(b.meta.classId),pause:b.pauseState()},null,2);}catch(e){out.textContent=e.stack;}};
document.getElementById('pauseQAStage').onclick=()=>{const b=__BF3,p=b.G.p;b.MP.zone=b.G.zone;b.MP.peers['qa-friend']=b.MP.mkPeer({...b.MP.selfState(),id:'qa-friend',name:'Test friend',cid:'pyromancer',skin:'wizard',x:p.x+48,z:p.z+10,y:p.y,busy:'Paused'});out.textContent='Friend staged';};
setInterval(()=>{const b=window.__BF3,q=b?.MP.peers['qa-friend'];if(q){q.last=0;out.dataset.rig=JSON.stringify(window.__hero3dInfo?.());}},100);
document.getElementById('pauseQAGrey').onclick=()=>{const b=__BF3;b.MP.peers['qa-friend'].busy='Paused';out.textContent='Friend grey: '+b.MP.peers['qa-friend'].busy;};
document.getElementById('pauseQAColor').onclick=()=>{const b=__BF3;b.MP.peers['qa-friend'].busy='';out.textContent='Friend resumed: full color';};
</script>'''
import json
payload=payload.replace('LEGACY_SAVE',json.dumps(json.loads((R/'docs/art-validation/hollow-review-20261015/canyon-arrival-before.json').read_text(encoding='utf8'))['save']))
source=(R/'public/3d/index.html').read_text(encoding='utf8').replace('<head>','<head><base href="/3d/">'+isolation,1).replace('if(m && m[1]!==VERSION3D)','if(false && m && m[1]!==VERSION3D)')
(R/'public/3d/.qa-esc-pause.html').write_text(source.replace('</body>',payload+'</body>'),encoding='utf8')
print('Built isolated pause fixture; real saves untouched.')
